      ]
    },
    {
      "claim": "Regulatory frameworks must require independent third parties—such as the US AI Safety Institute—to audit and validate these diagnostic sandboxes before any public release.",
      "targets": [
        "AN-10"
      ]
    }
  ],
  "key_assumptions": [
    {
      "assumption": "Independent statutory bodies like the US AI Safety Institute will possess the necessary compute resources and technical expertise to meaningfully audit frontier models.",
      "if_wrong": "Labs will easily bypass external audits through technical obfuscation, validating Skeptic's safety-washing critique and rendering the oversight performative."
    }
  ],
